<?php require 'config.php';requireLogin();if(empty($_SESSION['admin_access']))respond(['success'=>false,'message'=>'Admin access required.'],403);$columns=$pdo->query('DESCRIBE users')->fetchAll(PDO::FETCH_COLUMN);$status=in_array('status',$columns,true)?'status':"'active' AS status";$s=$pdo->query("SELECT id,name,email,$status FROM users ORDER BY id DESC");$stats=['matches'=>(int)$pdo->query('SELECT COUNT(*) FROM likes')->fetchColumn(),'messages'=>(int)$pdo->query('SELECT COUNT(*) FROM messages')->fetchColumn()];respond(['success'=>true,'users'=>$s->fetchAll(PDO::FETCH_ASSOC),'stats'=>$stats]);
